120     @Override
121     public DaemonClientConnection connect(ExplainingSpec<DaemonContext> constraint) {
122         final Pair<Collection<DaemonInfo>, Collection<DaemonInfo>> idleBusy = partitionByState(daemonRegistry.getAll(), Idle);
123         final Collection<DaemonInfo> idleDaemons = idleBusy.getLeft();
124         final Collection<DaemonInfo> busyDaemons = idleBusy.getRight();
125 
126         // Check to see if there are any compatible idle daemons
127         DaemonClientConnection connection = connectToIdleDaemon(idleDaemons, constraint);
128         if (connection != null) {
129             return connection;
130         }
131 
132         // Check to see if there are any compatible canceled daemons and wait to see if one becomes idle
133         connection = connectToCanceledDaemon(busyDaemons, constraint);
134         if (connection != null) {
135             return connection;
136         }
137 
138         // No compatible daemons available - start a new daemon
139         handleStopEvents(idleDaemons, busyDaemons);
140         return null;
141     }
